import { describe, expect, test } from 'bun:test'
import { SUITS, type Card } from '../../src/games/cards/model'
import { autoHome, cardsLeft, deal, emptyStats, hasLegalMove, legal, move, record, safeHome, snapshot, supermoveLimit, undo, validNumber, won,
  type Board, type Game } from '../../src/games/freecell/engine'

// External fixtures, not generated by the implementation under test:
// https://rosettacode.org/wiki/Deal_cards_for_FreeCell (task table and Ada output).
const fixtures: Record<number, string> = {
  1: `JD 2D 9H JC 5D 7H 7C 5H KD KC 9S 5S AD QC KH 3H 2S KS 9D QD JS AS AH 3C 4C 5C TS QH 4H AC 4D 7S
    3S TD 4S TH 8H 2C JH 7D 6D 8S 8D QS 6C 3D 8C TC 6S 9C 2H 6H`,
  617: `7D AD 5C 3S 5S 8C 2D AH TD 7S QD AC 6D 8H AS KH TH QC 3H 9D 6S 8D 3D TC KD 5H 9S 3C 8S 7H 4D JS
    4C QS 9C 9H 7C 6H 2C 2S 4S TS 2H 5D JC 6C JH QH JD KS KC 4H`,
  11982: `AH AS 4H AC 2D 6S TS JS 3D 3H QS QC 8S 7H AD KS KD 6H 5S 4D 9H JH 9S 3C JC 5D 5C 8C 9D TD KH 7C
    6C 2C TH QH 6D TC 4S 7S JD 7D 8H 9C 2H QD 4C 5H KC 8D 2S 3S`
}
const c = (rank: number, suit = 0): Card => ({ id: (rank - 1) * 4 + suit, rank, suit: SUITS[suit], faceUp: true })
function board(): Board { return { cascades: Array.from({ length: 8 }, () => []), free: [null, null, null, null], home: [0, 0, 0, 0] } }
function game(b: Board): Game { return { ...b, number: 1, history: [], cheat: false, moves: 0 } }

describe('Microsoft FreeCell', () => {
  for (const number of [1, 617, 11982]) test(`all 52 externally sourced cards for #${number}`, () => {
    const g = deal(number)
    fixtures[number].trim().split(/\s+/).forEach((token, i) => {
      const card = g.cascades[i % 8][Math.floor(i / 8)]
      expect('A23456789TJQK'[card.rank - 1] + 'CDHS'[SUITS.indexOf(card.suit)]).toBe(token)
    })
    expect(g.cascades.map(p => p.length)).toEqual([7, 7, 7, 7, 6, 6, 6, 6])
    expect(new Set(g.cascades.flat().map(c => c.id)).size).toBe(52)
    expect(deal(number)).toEqual(g)
  })
  test('hidden games fixed and distinct with every ace buried', () => {
    for (const number of [-1, -2]) {
      const g = deal(number)
      expect(deal(number)).toEqual(g)
      expect(g.cascades.slice(0, 4).map(p => p[0].rank)).toEqual([1, 1, 1, 1])
      expect(new Set(g.cascades.flat().map(c => c.id)).size).toBe(52)
    }
    expect(deal(-1).cascades).not.toEqual(deal(-2).cascades)
    expect(deal(-2).cascades[0].map(c => c.rank)).toEqual([1, 13, 12, 11, 10, 9, 8])
  })
  test('supermove excludes empty destination, counts occupied destination normally', () => {
    const b = board()
    b.cascades.forEach((p, i) => { if (i < 6) p.push(c(13, i % 4)) })
    expect(supermoveLimit(b, 0)).toBe(20)
    expect(supermoveLimit(b, 7)).toBe(10)
    b.free[0] = c(8)
    expect(supermoveLimit(b, 7)).toBe(8)
    b.free.fill(c(9))
    expect(supermoveLimit(b, 7)).toBe(2)
  })
  test('alternate descending runs obey exact capacity and any empty accepts a single', () => {
    const b = board()
    b.cascades.forEach((p, i) => p.push(c(13, i % 4)))
    b.cascades[0] = [c(7, 0), c(6, 1), c(5, 3)]
    b.cascades[1] = [c(8, 2)]
    b.free = [c(9), c(9, 1), c(9, 2), null]
    expect(legal(b, { kind: 'cascade', index: 0, depth: 0 }, { kind: 'cascade', index: 1 })).toBe(false)
    b.free[0] = null
    expect(legal(b, { kind: 'cascade', index: 0, depth: 0 }, { kind: 'cascade', index: 1 })).toBe(true)
    b.cascades[1] = []
    expect(legal(b, { kind: 'cascade', index: 0, depth: 2 }, { kind: 'cascade', index: 1 })).toBe(true)
  })
  test('safe home aces and twos unconditional, higher need both opposite predecessors', () => {
    const b = board()
    expect(safeHome(b, c(1))).toBe(true)
    b.home[0] = 1
    expect(safeHome(b, c(2))).toBe(true)
    b.home[0] = 4
    b.home[1] = 4
    b.home[2] = 3
    expect(safeHome(b, c(5))).toBe(false)
    b.home[2] = 4
    expect(safeHome(b, c(5))).toBe(true)
    b.home[0] = 3
    expect(safeHome(b, c(5))).toBe(false)
  })
  test('auto home repeats and undo restores all auto moves atomically', () => {
    const b = board()
    b.cascades[0] = [c(2), c(1)]
    b.cascades[1] = [c(2, 1), c(1, 1)]
    b.cascades[2] = [c(9, 3)]
    const g = game(b)
    const before = snapshot(g)
    const next = move(g, { kind: 'cascade', index: 2 }, { kind: 'free', index: 0 })!
    expect(next.home).toEqual([2, 2, 0, 0])
    expect(next.history).toHaveLength(1)
    expect(snapshot(undo(next))).toEqual(before)
    const next2 = move(next, { kind: 'free', index: 0 }, { kind: 'cascade', index: 3 })!
    expect(snapshot(undo(undo(next2)))).toEqual(before)
  })
  test('win detection, no legal moves and cheat deferred until a legal move', () => {
    const b = board()
    b.home.fill(13)
    expect(won(b)).toBe(true)
    expect(cardsLeft(b)).toBe(0)
    expect(hasLegalMove(b)).toBe(false)
    b.home[0] = 12
    expect(won(b)).toBe(false)
    const g = deal(1)
    g.cheat = true
    expect(won(g)).toBe(false)
    const next = move(g, { kind: 'cascade', index: 0 }, { kind: 'free', index: 0 })!
    expect(won(next)).toBe(true)
    expect(cardsLeft(next)).toBe(0)
    expect(won(undo(next))).toBe(false)
  })
  test('auto play does not send unsafe higher cards', () => {
    const b = board()
    b.home[0] = 4
    b.cascades[0] = [c(5)]
    autoHome(b)
    expect(b.home[0]).toBe(4)
  })
  test('statistics streak changes reset direction and preserve records', () => {
    let s = emptyStats()
    for (const win of [true, true, false, false, false, true]) s = record(s, win)
    expect(s).toEqual({ won: 3, lost: 3, bestWins: 2, bestLosses: 3, streak: 1 })
  })
  test('selection range includes hidden games and rejects other numbers', () => {
    for (const n of [1, 32000, -1, -2]) expect(validNumber(n)).toBe(true)
    for (const n of [0, 32001, -3, 1.5, NaN]) expect(validNumber(n)).toBe(false)
  })
})
